window.getEmployeeOKR = function(scenarioName, employeeIndex) {
  if (!window.PMS_OKR_DATA) return null;
  var s = window.PMS_OKR_DATA[scenarioName];
  if (!s || !s[employeeIndex]) return null;
  return s[employeeIndex];
};
